  +`<g transform="translate(318 96)"><g class="sp a-pulse"><circle r="26" fill="#fff"/><text y="2" font-size="34" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="#147a8a" font-family="sans-serif">?</text></g></g>`;
